import { createSignal } from "solid-js";

// A member of Array.prototype under a key the file builds at run time: any standard array member may be this function.
const key = ["a", "t"].join("");
const original = Array.prototype[key];
Array.prototype[key] = function (index) {
  return original.call(this, index);
};

export const touch = () => createSignal(0);
